"SiteTarget","description":"A single binding target for a vault entry. Tagged union over the discriminator `kind`. A VaultEntry\'s `targets` array MAY mix any number of these.","oneOf":[{"title":"WebOrigin","type":"object","additionalProperties":false,"required":["kind","origin"],"properties":{"kind":{"const":"webOrigin"},"origin":{"type":"string","format":"uri","description":"Web origin per RFC 6454 (scheme + host + optional port), e.g. \\"https://github.com\\". Compared by exact string equality after canonicalisation (lowercase host, default port elided). Consumers wanting subdomain coverage SHOULD add multiple targets, not encode a wildcard."}}},{"title":"Did","type":"object","additionalProperties":false,"required":["kind","did"],"properties":{"kind":{"const":"did"},"did":{"type":"string","minLength":1,"description":"DID identifying the relying party (e.g. did:web:rp.example). The vault maintainer is responsible for any DID resolution required to act on this entry."}}},{"title":"IosApp","type":"object","additionalProperties":false,"required":["kind","bundleId"],"properties":{"kind":{"const":"iosApp"},"bundleId":{"type":"string","minLength":1,"pattern":"^[A-Za-z0-9.-]+\$","description":"iOS bundle identifier in reverse-DNS form (e.g. \\"com.github.stwalkerster.codehub\\"). Compared by exact string equality. Matches when an iOS Companion identifies the requesting app via its bundle id (typically via the OS Credential Manager integration)."},"teamId":{"type":"string","minLength":1,"pattern":"^[A-Z0-9]+\$","description":"Optional Apple Developer Team identifier (10-character alphanumeric). When supplied, the maintainer SHOULD also verify the team id of the requesting app before matching — defense in depth against bundle-id squatting on jailbroken devices."}}},{"title":"AndroidApp","type":"object","additionalProperties":false,"required":["kind","packageName","sha256CertFingerprints"],"properties":{"kind":{"const":"androidApp"},"packageName":{"type":"string","minLength